def agent_action(sandbox, agent_body, step_count):
    # Check and initialize userData if needed
    if not hasattr(agent_body, 'userData'):
        agent_body.userData = {
            'unlock_steps': 0,
            'exit_steps': 0,
            'unlock_done': False
        }
    data = agent_body.userData

    # Retrieve current position and whisker readings
    pos = sandbox.get_agent_position()
    x, y = pos
    front, up, down = sandbox.get_whisker_readings()

    # Navigation logic using whiskers
    fy = 0.0
    front_threshold = 0.3  # meters

    # Adjust y-direction based on front, up, and down whiskers
    if front < front_threshold:
        # Obstacle detected ahead; adjust y-direction to navigate around
        if up < down:
            fy = -10.0  # Move down
        else:
            fy = 10.0   # Move up
    else:
        # No front obstacle; check up and down whiskers
        if up < 0.3 and up < down:
            fy = -10.0  # Move down
        elif down < 0.3 and down < up:
            fy = 10.0   # Move up
        else:
            fy = 0.0

    # Determine forward/backward force
    fx = 0.0

    if not data['unlock_done']:
        # If in unlock zone [5.0, 10.0], apply backward force to unlock
        if 5.0 <= x <= 10.0:
            fx = -35.0  # Strictly less than -34.0 N
            vel = sandbox.get_agent_velocity()
            true_speed = (vel[0]**2 + vel[1]**2)**0.5
            if true_speed < 100.0:  # Ensure speed constraint
                data['unlock_steps'] += 1
                if data['unlock_steps'] >= 5:
                    data['unlock_done'] = True
            else:
                # If speed too high, revert to forward force
                fx = 50.0
        else:
            # Not in unlock zone, apply forward force to move toward the unlock zone
            fx = 50.0  # Moderate forward force to avoid excessive acceleration
    else:
        # After unlock, apply forward force to reach exit zone
        fx = 50.0
        # Check if in exit zone
        if x >= 15.0 and 0.5 <= y <= 2.5:
            data['exit_steps'] += 1
            if data['exit_steps'] >= 5:
                # Task complete, no further action needed
                return
        else:
            # Continue forward movement
            pass

    # Apply forces
    sandbox.apply_agent_force(fx, fy)

